'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={step:1,mode:'create',files:[],source:'',title:'',audience:'',pageCount:'',content:'',course:'',style:'清晰简洁，适合投影',templateFile:null,supplementsOpen:false,presenter:'',lessonDate:'',minutes:20,extra:'',template:'不使用模板',method:'auto',phase:'outline',approved:false,demo:false};let unmount,unmountTemplate,uid=0,lastStep=0;
const pptFiles=()=>state.files.filter(f=>/\.pptx$/i.test(f.name));
const rows=[['封面','课程主题与原稿授课信息','封面布局','更新标题层级与留白'],['核心概念','定义、术语、原图与论点','左文右图','保留原图，调整图文比例'],['案例讲解','案例背景、原数据、引用来源','双栏对比','将已有信息分区，不新增案例'],['练习与总结','原题、答案、总结与教学备注','要点布局','整理层次，答案保留在原位置或原备注']];
state.layouts=rows.map(r=>r[2]);
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',2800);}
function steps(){const labels=['填写要求','选择方式',state.mode==='update'?'确认更新方案':'生成大纲','生成PPT'];$('steps').innerHTML=labels.map((t,i)=>`<span class="${state.step===i+1?'on':''}"><i>${i+1}</i>${t}</span>`).join('');}
function footer(next,label){return `<div class="footer"><button data-action="back">← ${state.step===1?'返回PPT管理':'上一步'}</button>${next?`<button class="primary" data-action="${next}">${label}</button>`:''}</div>`;}
function render(){unmount?.();unmount=null;unmountTemplate?.();unmountTemplate=null;steps();if(state.step===1)requirements();else if(state.step===2)method();else if(state.step===3)plan();else result();if(state.step!==lastStep){const main=document.querySelector?.('.sh-main');if(main)main.scrollTop=0;lastStep=state.step;}}
function requirements(){const ppts=pptFiles(),updating=state.mode==='update';$('view').innerHTML=`<section class="panel"><div class="inline" style="justify-content:space-between"><h2>这节课的要求</h2><button data-action="demo">载入演示资料</button></div><div class="fields"><div class="wide"><label for="title">本课主题</label><input id="title" maxlength="80" value="${esc(state.title)}" placeholder="${updating?'可沿用原课件名称':'填写本课主题'}"></div><div><label for="presenter">授课人 <small>选填，显示在封面</small></label><input id="presenter" maxlength="60" value="${esc(state.presenter)}" placeholder="例如：李老师"></div><div><label for="lessonDate">授课日期 <small>选填，显示在封面</small></label><input id="lessonDate" type="date" value="${esc(state.lessonDate)}"></div><div><label for="audience">授课对象</label><input id="audience" maxlength="100" value="${esc(state.audience)}" placeholder="例如：高一，已学习古典概型"><p class="muted">${updating?'用于讲稿表达，不据此擅自改写原稿知识点。':''}</p></div><div><label for="minutes">课时 <small>分钟</small></label><input type="number" id="minutes" min="5" max="240" value="${state.minutes}"><p class="muted">${updating?'仅用于讲稿节奏，不据此压缩或删除原稿。':''}</p></div><div><label for="pageCount">PPT 页数 <small>页，可选</small></label><input id="pageCount" type="number" min="1" max="150" step="1" value="${esc(state.pageCount)}" placeholder="${updating?'留空保留原页数':'留空自动安排'}"><p class="muted">${updating?'默认保留原页数；指定不同页数时先提出拆合页方案，确认后才执行。':'包含封面和结束页，共1–150页；页数越多，制作时间越长。'}</p></div><div><label for="course">关联课程</label><select id="course">${['暂不关联课程','人工智能安全 · 示例课程','数学 · 示例课程'].map(t=>`<option ${state.course===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="style">视觉风格</label><input id="style" maxlength="100" value="${esc(state.style)}"></div><div class="wide"><label for="content">教学内容或参考资料</label><textarea id="content" maxlength="12000" placeholder="知识点、教材章节或课堂安排">${esc(state.content)}</textarea><p class="muted">${updating?'可补充本次关注的内容；原稿仍为内容依据，不自动用此处文字替换原稿。':'填写内容或上传参考资料，选一种即可。'}</p></div><div class="wide"><div id="upload"></div><p id="uploadError" class="error" role="alert"></p><p class="muted">资料保存在本机；交给WorkBuddy制作时由其模型服务处理，请勿上传不宜外发的资料。本原型不上传文件。</p><p class="muted">上传PPTX后可选择更新课件。传统.ppt格式请先另存为.pptx。</p></div></div><h3 style="margin-top:22px">本次希望怎么制作？</h3><div class="mode"><button data-action="create" aria-pressed="${!updating}"><strong>新建内容</strong><small>从教学要求和参考资料组织一份新课件。</small></button><button data-action="update" aria-pressed="${updating}" ${ppts.length?'':'disabled'}><strong>更新课件</strong><small>${ppts.length?'保留旧PPT内容和顺序，更新模板与排版。':'先上传一份PPTX原稿，再选择此模式。'}</small></button></div>${updating?`<div class="hint">原稿决定内容，模板决定视觉。保留主要内容、数据、例题及必要原图；内容变更先确认。</div><label for="source">要更新的原稿${ppts.length>1?'（其余文件作为补充资料）':''}</label><select id="source">${ppts.map(f=>`<option ${state.source===f.name?'selected':''}>${esc(f.name)}</option>`).join('')}</select><p class="muted">${state.demo?'演示原稿为4页；非真实解析结果。':'本原型不解析原页数，后续4页方案为演示数据。'}</p><div class="policy"><span>✓ 按原页数与原顺序</span><span>✓ 不自动删改数据与例题</span><span>✓ 保留必要原图</span></div>`:''}<section class="template-section"><h3>课件模板（可选）</h3><a href="ppt-templates.html#list" target="_blank" rel="noopener">管理模板库 ↗</a><p class="muted">${updating?'复用模板的字体、配色和版式，保留原稿内容。':'复用模板的字体、配色和版式，课程内容按本次要求制作。'}原型模板选项为示例，不连接正式模板库。</p><label for="template">选择已保存模板</label><select id="template">${['不使用模板','蓝白教学模板','深蓝简约模板',...(state.templateFile?[state.templateFile.name]:[])].map(t=>`<option ${state.template===t?'selected':''}>${esc(t)}</option>`).join('')}</select><div id="templateUpload" style="margin-top:18px"></div><p id="templateError" class="error" role="alert"></p><p class="muted">上传模板后，正式流程需拆解并确认可复用布局；原型仅记录名称，不解析模板。</p></section><details id="supplements" ${state.supplementsOpen?'open':''}><summary>补充要求（可选）</summary><div class="fields" style="margin-top:18px"><div class="wide"><textarea id="extra" aria-label="补充要求" maxlength="1000" placeholder="可自由填写其他要求，例如希望保留的内容、需要调整的地方或课堂安排。">${esc(state.extra)}</textarea></div></div></details><p id="formError" class="error" role="alert"></p><div class="footer"><button data-action="back">返回列表</button><div class="inline"><button data-action="save">保存草稿</button><button class="primary" data-action="next">下一步：选择制作方式 →</button></div></div><p id="draftStatus" class="muted" role="status"></p></section>`;
for(const id of ['title','presenter','lessonDate','audience','minutes','pageCount','content','course','style','extra','template','source'])if($(id))$(id).oninput=e=>{state[id]=e.target.value;state.approved=false;};$('supplements').ontoggle=e=>state.supplementsOpen=e.target.open;
unmount=window.InclassUpload.mount($('upload'),{accept:'.pptx,.pdf,.docx,.txt,.md,.png,.jpg,.jpeg',multiple:true,limit:12,types:'PDF、Word、PPTX、文本、图片 · 每份不超过20MB，最多12份',files:state.files,getFiles:()=>state.files,onSelect:files=>{if(files.some(f=>!f.size||f.size>20*1024*1024||!/\.(pptx|pdf|docx|txt|md|png|jpe?g)$/i.test(f.name))){$('uploadError').textContent='请选择支持的非空文件，每份不超过20MB。';return;}if(state.files.length+files.length>12){$('uploadError').textContent='最多12份资料。';return;}state.files.push(...files.map(f=>({name:f.name,size:f.size,uid:++uid,status:'success'})));state.source||=pptFiles()[0]?.name||'';state.demo=false;state.approved=false;render();},onRemove:file=>{state.files=state.files.filter(f=>f.uid!==file.uid);if(!pptFiles().some(f=>f.name===state.source))state.source=pptFiles()[0]?.name||'';if(!pptFiles().length){state.mode='create';toast('已移除PPT原稿，恢复为新建内容模式');}state.approved=false;render();},onError:t=>$('uploadError').textContent=t});
unmountTemplate=window.InclassUpload.mount($('templateUpload'),{accept:'.pptx',multiple:false,limit:1,label:'将PPT模板拖到此处，或',types:'PPTX · 不超过20MB · 原型仅记录名称',files:state.templateFile?[state.templateFile]:[],getFiles:()=>state.templateFile?[state.templateFile]:[],onSelect:files=>{const f=files[0];if(files.length!==1||!/\.pptx$/i.test(f.name)||!f.size||f.size>20*1024*1024){$('templateError').textContent='请选择一份非空且不超过20MB的PPTX模板。';return;}state.templateFile={uid:++uid,name:f.name,size:f.size,status:'success'};state.template=f.name;state.approved=false;render();},onRemove:()=>{if(state.template===state.templateFile?.name)state.template='不使用模板';state.templateFile=null;state.approved=false;render();},onError:t=>$('templateError').textContent=t});}
function prompt(){return window.PptUpdatePrompt.build({sourceName:state.source,templateName:state.template==='不使用模板'||state.template.startsWith('不指定')?'':state.template,title:state.title,audience:state.audience,pageCount:state.pageCount,content:state.content,course:state.course,style:state.style,presenter:state.presenter,lessonDate:state.lessonDate,minutes:state.minutes,extra:state.extra,phase:state.phase});}
function method(){$('view').innerHTML=`<section class="panel"><h2>${state.mode==='update'?'更新课件':'新建课件'} · 选择制作方式</h2><div class="mode">${[['auto','平台交接','在平台确认方案、检查课件并导出。'],['manual','手动交给WorkBuddy','复制专用任务文本，并另外附上原稿与模板。']].map(([key,name,desc])=>`<button data-action="method-${key}" aria-pressed="${state.method===key}"><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="hint">${state.mode==='update'?`内容原稿：${esc(state.source)}<br>视觉模板：${esc(state.template)}<br>先核对逐页更新方案，再制作成品。`:'新建内容按原有教学大纲流程处理，本原型主要演示更新课件分支。'}</div>${state.mode==='update'?`<details open><summary>查看交给WorkBuddy的专用提示词</summary><div class="tabbar">${[['outline','更新方案'],['html','逐页制作'],['export','导出PPT']].map(([key,label])=>`<button data-action="phase-${key}" class="${state.phase===key?'selected':''}">${label}</button>`).join('')}</div><textarea id="prompt" class="prompt" readonly aria-label="更新课件专用提示词">${esc(prompt())}</textarea><button data-action="copy">复制当前阶段提示词</button><p class="muted">文件不会随文字复制；手动调用时请另附原PPT与模板。阶段间需教师确认，不能一次执行全部阶段。</p></details>`:''}</section>${footer('plan','查看逐页更新方案（演示） →')}`;}
function plan(){$('view').innerHTML=`<section class="panel"><h2>${state.mode==='update'?'确认逐页更新方案':'逐页大纲'} <span class="pill">演示数据</span></h2><p>以下4页仅用于体验交互，不代表已读取上传文件。</p>${state.mode==='update'&&state.pageCount?`<p class="hint">填写的目标为${esc(state.pageCount)}页；正式方案需先与原页数比较，再由老师确认拆合页。当前演示仍展示4页，不代表已满足目标页数。</p>`:''}<div class="hint">${state.mode==='update'?'默认原页数、顺序和内容不变，内容变更建议为0项。每页先核对保留内容，再看视觉调整。':'本分支演示普通新建内容的大纲；更新模式会额外保留来源映射及内容核对。'}</div>${rows.map((r,i)=>`<article class="plan-row"><span>原第${i+1}页<br>↓<br>新第${i+1}页</span><div><h3>${r[0]}</h3><span class="pill">${state.mode==='update'?'内容保留':'示例内容'}</span><p>${r[1]}</p></div><div><label>拟用布局</label><select aria-label="第${i+1}页布局"><option ${state.layouts[i]===r[2]?'selected':''}>${r[2]}</option><option ${state.layouts[i]==='沿用原页结构'?'selected':''}>沿用原页结构</option></select><p>仅视觉：${r[3]}</p></div></article>`).join('')}<details><summary>需要老师处理的情况</summary><p>正文读不清、公式不确定、模板放不下、建议拆页或资料疑似过时，会显示原页和影响，等待老师处理；未经确认保持原内容，不自动补写、更新事实或删页。</p></details><label class="check" style="margin-top:22px"><input id="approved" type="checkbox" ${state.approved?'checked':''}>我已核对本次更新范围，按上述方案保留原内容并更新排版（演示确认）。</label><p id="planError" class="error" role="alert"></p></section>${footer('generate','确认方案，生成PPT（演示） →')}`;$('approved').onchange=e=>state.approved=e.target.checked;document.querySelectorAll('.plan-row select').forEach((el,i)=>el.onchange=e=>{state.layouts[i]=e.target.value;state.approved=false;$('approved').checked=false;});}
function result(){$('view').innerHTML=`<section class="panel"><h2>更新后的课件 <span class="pill">静态示例</span></h2><div class="preview"><h2>${esc(state.title||'课程主题')}</h2><p>${esc(state.presenter||'沿用原稿授课信息')}</p><p>${esc(state.lessonDate||'保留原稿日期')}</p></div><div class="hint">原稿4页 → 新课件4页 · 演示内容保留清单已展示；此处未实际生成或核验上传文件。</div><h3>检查与导出</h3><p>正式流程将逐页对照原稿核对正文、数据、公式、表格及图片，另外交付逐页讲稿；需要人工核对的对象单独列出。</p><div class="inline"><button data-action="review">返回更新方案查看</button><button data-action="export">导出可编辑PPT（演示）</button></div></section>${footer(null)}`;}
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='demo'){state.files=[{uid:++uid,name:'旧版教学课件.pptx',size:1024,status:'success'}];state.source=state.files[0].name;state.title||='人工智能安全导论';state.audience||='大学一年级学生';state.demo=true;state.approved=false;render();toast('演示资料已载入，请明确选择是否更新课件');}else if(action==='create'||action==='update'){if(action==='update'&&!pptFiles().length)return;state.mode=action;state.approved=false;render();}else if(action==='back'){if(state.step===1){location.href='ppt-preparation.html#list';return;}state.step--;render();}else if(action==='save'){try{localStorage.setItem('inclass.prototype.ppt-update.draft',JSON.stringify(state));$('draftStatus').textContent='原型草稿已保存到当前浏览器：表单及文件名称会保留，不上传文件。';toast('原型草稿已保存');}catch{$('formError').textContent='当前浏览器无法保存草稿，已填内容仍保留在页面。';}}else if(action==='next'){if(state.minutes<5||state.minutes>240||!Number.isInteger(Number(state.minutes))){$('formError').textContent='课时请填写5至240之间的整数。';return;}if(state.pageCount!==''&&(!Number.isInteger(Number(state.pageCount))||Number(state.pageCount)<1||Number(state.pageCount)>150)){$('formError').textContent='PPT页数请填写1至150之间的整数，或留空。';return;}if(state.mode==='create'&&(!state.title.trim()||!state.audience.trim()||(!state.content.trim()&&!state.files.length))){$('formError').textContent='请填写本课主题、授课对象，以及教学内容或参考资料。';return;}if(state.mode==='update'&&!state.source){$('formError').textContent='请选择要更新的PPTX原稿。';return;}state.step=2;render();}else if(action.startsWith('method-')){state.method=action.slice(7);render();}else if(action.startsWith('phase-')){state.phase=action.slice(6);render();}else if(action==='copy'){try{await navigator.clipboard.writeText(prompt());toast('当前阶段提示词已复制');}catch{toast('复制未完成，请在文本框中手动复制');}}else if(action==='plan'){state.step=3;render();}else if(action==='generate'){if(!state.approved){$('planError').textContent='请先整体核对并确认更新方案。';return;}state.step=4;render();}else if(action==='review'){state.step=3;render();}else if(action==='export')toast('原型不生成文件；正式流程将在确认课件后导出。');});
try{const draft=JSON.parse(localStorage.getItem('inclass.prototype.ppt-update.draft'));if(draft){for(const key of ['title','presenter','lessonDate','audience','pageCount','content','course','style','extra'])if(typeof draft[key]==='string')state[key]=draft[key];if(Number.isInteger(Number(draft.minutes))&&draft.minutes>=5&&draft.minutes<=240)state.minutes=Number(draft.minutes);state.files=Array.isArray(draft.files)?draft.files.filter(f=>typeof f.name==='string'&&f.size>0&&f.size<=20*1024*1024).slice(0,12).map(f=>({...f,uid:++uid})):[];if(draft.templateFile?.name&&/\.pptx$/i.test(draft.templateFile.name))state.templateFile={...draft.templateFile,uid:++uid};state.template=typeof draft.template==='string'?draft.template:'不使用模板';state.source=pptFiles().some(f=>f.name===draft.source)?draft.source:pptFiles()[0]?.name||'';state.mode=draft.mode==='update'&&state.source?'update':'create';state.demo=!!draft.demo;}}catch{}
render();
